// LLM 응답을 Kuromoji sentences 구조와 병합
const llm = JSON.parse($json.choices[0].message.content);
const src = $node['Tokenize Sentences (Kuromoji)'].json;
const rssItem = $node['Dedupe (max 20)'].json;
const kSentences = src.sentences || [];
const lSentences = (llm.sentences || []).reduce((m, s) => { m[s.idx] = s; return m; }, {});
const sentences = kSentences.map(s => {
  const ls = lSentences[s.idx] || { text_ko: '', token_meanings: [] };
  return {
    idx: s.idx,
    text_jp: s.text_jp,
    text_ko: ls.text_ko || '',
    tokens: s.tokens.map((t, i) => ({
      surface: t.surface,
      reading: t.reading,
      meaning: (ls.token_meanings || [])[i] || '',
      pos: t.pos,
      startIdx: t.startIdx,
      endIdx: t.endIdx
    }))
  };
});
const flatTokens = sentences.flatMap(s => s.tokens);
return [{
  json: {
    source: 'NHK',
    source_url: rssItem.link,
    title_jp: rssItem.title,
    title_ko: llm.title_ko,
    body_jp: rssItem.contentSnippet || rssItem.title,
    body_ko: llm.body_ko,
    tokens: flatTokens,
    sentences,
    difficulty: ['N5','N4','N3','N2','N1'].includes(llm.difficulty) ? llm.difficulty : null,
    published_at: rssItem.pubDate
  }
}];
